private String findPrevious(TableColumn tableColumn, Table newTable) { int index = newTable.getColumnList().indexOf(tableColumn); if (index == 0) { return "-1"; } for (int i = index - 1; i >= 0; i--) { if (newTable.getColumnList().get(i).getEditStatus() == null || !newTable.getColumnList().get(i).getEditStatus().equals(EditStatus.DELETE.name())) { return newTable.getColumnList().get(i).getName(); } } return "-1"; } public String buildGenerateReorderColumnSql(Table oldTable, Table newTable) { StringBuilder sql = new StringBuilder(); int n = 0; Map<String, Integer> oldColumnIndexMap = new HashMap<>(); for (int i = 0; i < oldTable.getColumnList().size(); i++) { oldColumnIndexMap.put(oldTable.getColumnList().get(i).getName(), i); } String[] oldColumnArray = oldTable.getColumnList().stream().map(TableColumn::getName).toArray(String[]::new); String[] newColumnArray = newTable.getColumnList().stream().map(TableColumn::getName).toArray(String[]::new); Set<String> oldColumnSet = new HashSet<>(Arrays.asList(oldColumnArray)); Set<String> newColumnSet = new HashSet<>(Arrays.asList(newColumnArray)); if (!oldColumnSet.equals(newColumnSet)) { return ""; } buildSql(oldColumnArray, newColumnArray, sql, oldTable, newTable, n); return sql.toString(); } private String[] buildSql(String[] originalArray, String[] targetArray, StringBuilder sql, Table oldTable, Table newTable, int n) { if (!originalArray[0].equals(targetArray[0])) { int a = findIndex(originalArray, targetArray[0]); TableColumn column = oldTable.getColumnList().stream().filter(col -> StringUtils.equals(col.getName(), originalArray[a])).findFirst().get(); String[] newArray = moveElement(originalArray, a, 0, targetArray, new AtomicInteger(0)); sql.append(" MODIFY COLUMN "); MysqlColumnTypeEnum typeEnum = MysqlColumnTypeEnum.getByType(column.getColumnType()); sql.append(typeEnum.buildColumn(column)); sql.append(" FIRST;
"); n++; if (Arrays.equals(newArray, targetArray)) { return newArray; } String[] resultArray = buildSql(newArray, targetArray, sql, oldTable, newTable, n); if (Arrays.equals(resultArray, targetArray)) { return resultArray; } } int max = originalArray.length - 1; if (!originalArray[max].equals(targetArray[max])) { int a = findIndex(originalArray, targetArray[max]); TableColumn column = oldTable.getColumnList().stream().filter(col -> StringUtils.equals(col.getName(), originalArray[a])).findFirst().get(); String[] newArray = moveElement(originalArray, a, max, targetArray, new AtomicInteger(0)); if (n > 0) { sql.append("ALTER TABLE "); if (StringUtils.isNotBlank(oldTable.getDatabaseName())) { sql.append("`").append(oldTable.getDatabaseName()).append("`").append("."); } sql.append("`").append(oldTable.getName()).append("`").append("
"); } sql.append(" MODIFY COLUMN "); MysqlColumnTypeEnum typeEnum = MysqlColumnTypeEnum.getByType(column.getColumnType()); sql.append(typeEnum.buildColumn(column)); sql.append(" AFTER "); sql.append(oldTable.getColumnList().get(max).getName()); sql.append(";
"); n++; if (Arrays.equals(newArray, targetArray)) { return newArray; } String[] resultArray = buildSql(newArray, targetArray, sql, oldTable, newTable, n); if (Arrays.equals(resultArray, targetArray)) { return resultArray; } } for (int i = 0; i < originalArray.length; i++) { int a = findIndex(targetArray, originalArray[i]); if (i != a && isMoveValid(originalArray, targetArray, i, a)) { int finalI = i; TableColumn column = oldTable.getColumnList().stream().filter(col -> StringUtils.equals(col.getName(), originalArray[finalI])).findFirst().get(); if (n > 0) { sql.append("ALTER TABLE "); if (StringUtils.isNotBlank(oldTable.getDatabaseName())) { sql.append("`").append(oldTable.getDatabaseName()).append("`").append("."); } sql.append("`").append(oldTable.getName()).append("`").append("
"); } sql.append(" MODIFY COLUMN "); MysqlColumnTypeEnum typeEnum = MysqlColumnTypeEnum.getByType(column.getColumnType()); sql.append(typeEnum.buildColumn(column)); sql.append(" AFTER "); AtomicInteger continuousDataCount = new AtomicInteger(0); String[] newArray = moveElement(originalArray, i, a, targetArray, continuousDataCount); if (i < a) { sql.append(originalArray[a + continuousDataCount.get()]); } else { sql.append(originalArray[a - 1]); } sql.append(";
"); n++; if (Arrays.equals(newArray, targetArray)) { return newArray; } String[] resultArray = buildSql(newArray, targetArray, sql, oldTable, newTable, n); if (Arrays.equals(resultArray, targetArray)) { return resultArray; } } } return null; } buildSql moveElement

private String dot(MavenResolutionResult mrr) { StringBuilder dot = new StringBuilder("digraph main {
"); Map<ResolvedGroupArtifactVersion, Integer> index = new HashMap<>(); ResolvedGroupArtifactVersion root = new ResolvedGroupArtifactVersion(null, mrr.getPom().getGroupId(), mrr.getPom().getArtifactId(), mrr.getPom().getVersion(), null); dotLabel(dot, 0, root); index.put(root, 0); for (Scope scope : Scope.values()) { if (scope.ordinal() < Scope.Compile.ordinal() || Scope.Test.ordinal() < scope.ordinal()) { continue; } List<ResolvedDependency> resolvedDependencies = mrr.getDependencies().get(scope); if (resolvedDependencies == null) { continue; } for (ResolvedDependency dep : resolvedDependencies) { if (!index.containsKey(dep.getGav())) { dotLabel(dot, index.size(), dep.getGav()); index.put(dep.getGav(), index.size()); } } } Set<ResolvedGroupArtifactVersion> seen = newSetFromMap(new IdentityHashMap<>()); for (Scope scope : Scope.values()) { if (scope.ordinal() < Scope.Compile.ordinal() || Scope.Test.ordinal() < scope.ordinal()) { continue; } dotEdges(dot, root, scope, mrr.getDependencies().get(scope).stream().filter(dep -> dep.isDirect() && seen.add(dep.getGav())).collect(toList()), index); } dot.append("}"); return dot.toString(); } private void dotLabel(StringBuilder dot, int index, ResolvedGroupArtifactVersion gav) { dot.append(index).append(" [label="").append(gav.getGroupId()).append(":").append(gav.getArtifactId()).append(":").append(gav.getVersion()).append(""];
"); } private void dotEdges(StringBuilder dot, ResolvedGroupArtifactVersion head, Scope scope, List<ResolvedDependency> resolvedDependencies, Map<ResolvedGroupArtifactVersion, Integer> index) { int headIndex = index.get(head); for (ResolvedDependency dep : resolvedDependencies) { dot.append(headIndex).append(" -> ").append(index.get(dep.getGav())).append(" [taillabel="").append(scope).append(""];
"); dotEdges(dot, dep.getGav(), scope, dep.getDependencies(), index); } } dotEdges

