"); asyncContext.write(sqlBuilder.toString()); } } } @Override public void updateProcedure(Connection connection, String databaseName, String schemaName, Procedure procedure) throws SQLException { try { connection.setAutoCommit(false); String procedureBody = procedure.getProcedureBody(); boolean isCreateOrAlter = procedureBody.trim().toUpperCase().startsWith("CREATE OR ALTER "); if (procedureBody == null || !procedureBody.trim().toUpperCase().startsWith("CREATE")) { throw new IllegalArgumentException("No CREATE statement found."); } String procedureNewName = getSchemaOrProcedureName(procedureBody, schemaName, procedure); if (!procedureNewName.equals(procedure.getProcedureName())) { procedureBody = procedureBody.replace(procedure.getProcedureName(), procedureNewName); } String checkProcedureSQL = String.format(PROCEDURE_SQL, procedure.getProcedureName().toUpperCase(), schemaName.toUpperCase()); String finalProcedureBody = procedureBody; SQLExecutor.getInstance().execute(connection, checkProcedureSQL, resultSet -> { if (resultSet.next()) { int count = resultSet.getInt(1); if (count >= 1) { if (isCreateOrAlter) { SQLExecutor.getInstance().execute(connection, finalProcedureBody, resultSet2 -> { }); } else { throw new SQLException("Procedure with the same name already exists."); } } } }); SQLExecutor.getInstance().execute(connection, finalProcedureBody, resultSet -> { }); } catch (Exception e) { connection.rollback(); throw new RuntimeException(e); } finally { connection.setAutoCommit(true); } } @Override public void connectDatabase(Connection connection, String database) { try { SQLExecutor.getInstance().execute(connection, "use [" + database + "];"); } catch (SQLException e) { throw new RuntimeException(e); } } @Override public void copyTable(Connection connection, String databaseName, String schemaName, String tableName, String newTableName, boolean copyData) throws SQLException { String sql = ""; if (copyData) { sql = "SELECT * INTO " + newTableName + " FROM " + tableName; } else { sql = "SELECT * INTO " + newTableName + " FROM " + tableName + " WHERE 1=0"; } SQLExecutor.getInstance().execute(connection, sql, resultSet -> null); } private static String getSchemaOrProcedureName(String procedureBody, String schemaName, Procedure procedure) { if (procedureBody.toLowerCase().contains(schemaName.toLowerCase())) { return procedure.getProcedureName(); } else { return schemaName + "." + procedure.getProcedureName(); } }
